#chat .mes .mes_text { order: 2; padding: 22px 24px; font-family: var(--mainFontFamily); font-size: var(--cc-font-size); line-height: var(--cc-line-height); font-weight: 400; color: var(--cc-ink); }
#chat .mes .mes_text p { margin: 0 0 .85em; }
