#chat .mes[is_system="true"] .mes_text { font-size: 14px; color: var(--cc-muted); }
#chat .mes .mes_buttons { opacity: 1; color: var(--cc-muted); gap: 4px; }
#chat .mes .mes_button { min-width: 28px; min-height: 28px; padding: 6px; border-radius: 8px; opacity: .8; }
#chat .mes .mes_button:hover { opacity: 1; color: var(--cc-accent-ink); background: var(--cc-user); }
#chat .mes .mes_edit_buttons { flex-wrap: wrap; gap: 6px; }
#chat .mes .extraMesButtons { background: var(--cc-base); border-radius: 12px; box-shadow: var(--cc-small); z-index: 4; }
#chat .mes :is(.edit_textarea, .reasoning_edit_textarea) { width: 100%; border-radius: 16px; padding: 16px; background: var(--cc-base); color: var(--cc-ink); box-shadow: var(--cc-inset); font-size: var(--cc-font-size); line-height: 1.75; }
/* Compact native toggle: every pixel of the collapsed pill belongs to the header. */
#chat .mes .mes_reasoning_details { order: 1; margin: 16px 24px 4px; border: 0; background: transparent; border-radius: 10px; overflow: hidden; }
#chat .mes .mes_reasoning_summary { margin: 0; width: fit-content; max-width: 100%; min-width: 0; padding: 0; gap: 0; background: var(--cc-base); color: var(--cc-accent-ink); border-radius: 10px; box-shadow: var(--cc-inset); min-height: 0; cursor: pointer; }
#chat .mes .mes_reasoning_header_block { min-width: 0; margin: 0; padding: 0; gap: 0; }
#chat .mes .mes_reasoning_header { position: relative; box-sizing: border-box; width: 100%; min-width: 0; min-height: 38px; margin: 0; padding: 8px 38px 8px 14px; border: 0; border-radius: 10px; box-shadow: none; background: none; font-size: 12px; }
