#chat .mes .mes_reasoning_header:hover { background: color-mix(in srgb, var(--cc-accent-ink) 6%, transparent); }
#chat .mes .mes_reasoning_header:focus-visible { outline: 2px solid var(--cc-accent-ink); outline-offset: -2px; }
#chat .mes .mes_reasoning { margin: 0; padding: 16px 10px 8px; color: var(--cc-muted); font-size: 14px; line-height: 1.75; }
#chat .mes :is(.mes_media_wrapper, .mes_file_wrapper) { order: 3; max-width: 100%; padding-inline: 20px; }
