#chat .mes .swipes-counter { margin: 0; height: 28px; align-items: center; opacity: .8; font-variant-numeric: tabular-nums; }
#chat .mes blockquote { border-left: 3px solid var(--cc-accent); margin: 1em 0; padding: 8px 16px; color: var(--cc-muted); background: color-mix(in srgb, var(--cc-accent) 7%, transparent); border-radius: 0 10px 10px 0; }
#chat .mes pre { position: relative; overflow: auto; max-width: 100%; border-radius: 14px; box-shadow: var(--cc-inset); border: 1px solid var(--SmartThemeBorderColor); padding: 16px; background: var(--cc-base); }
#chat .mes code { text-shadow: none; font-size: .86em; }
#chat .mes :not(pre) > code { background: var(--cc-user); border-radius: 5px; padding: 2px 5px; color: var(--cc-accent-ink); }
