#chat .mes a { color: var(--cc-accent-ink); text-underline-offset: 3px; }
#chat .mes.selected .mes_block::before { outline: 2px solid var(--cc-accent); }
body.hideChatAvatars #chat .mes { grid-template-columns: minmax(0, 1fr); }
body.hideChatAvatars #chat .mes .mes_block { grid-column: 1; }
#form_sheld { flex: 0 0 auto; min-width: 0; margin: 0; padding: 0 18px; }
#send_form { padding: 14px; border-radius: 26px; border: 1px solid var(--cc-edge); background: var(--cc-base); box-shadow: var(--cc-lift); backdrop-filter: none; }
#nonQRFormItems { gap: 12px; align-items: flex-end; min-width: 0; }
#send_textarea { min-width: 0; min-height: 56px; max-height: min(30dvh, 260px); flex: 1 1 auto; margin: 0; border: 1px solid transparent; border-radius: 18px; padding: 16px 18px; background: var(--cc-base); color: var(--cc-ink); box-shadow: var(--cc-inset); font-family: var(--mainFontFamily); font-size: 16px; line-height: 1.5; overflow-y: auto; }
#send_textarea::placeholder { color: var(--cc-muted); opacity: 1; }
#leftSendForm, #rightSendForm { width: auto; flex: 0 0 auto; flex-wrap: nowrap; padding: 0; gap: 8px; align-items: center; align-self: flex-end; }
#rightSendForm { max-width: 35%; }
#rightSendForm > div:not(.displayNone), #leftSendForm > div { width: 48px; height: 52px; border-radius: 16px; background: var(--cc-base); color: var(--cc-muted); box-shadow: var(--cc-small); opacity: 1; border: 1px solid color-mix(in srgb, var(--cc-edge) 65%, transparent); font-size: 20px; transition: color 140ms, box-shadow 140ms; }
