#top-settings-holder { position: absolute; z-index: auto !important; inset: 20px auto 20px 18px; margin: 0; width: 72px; height: calc(100dvh - 40px); display: flex; flex-direction: column; justify-content: flex-start; gap: 10px; padding: 12px 8px; border-radius: 24px; background: transparent; box-shadow: none; border: 1px solid transparent; pointer-events: none; }
