.drawer-content, #movingDivs > .drawer-content { background: var(--cc-base); color: var(--cc-ink); border: 1px solid var(--cc-edge); border-radius: 24px; padding: 22px; box-shadow: var(--cc-lift); backdrop-filter: none; text-shadow: none; }
#top-settings-holder .drawer-content { position: fixed; z-index: 3005; pointer-events: auto; top: 22px; left: 108px; right: auto; margin: 0; width: min(560px, calc(100vw - 130px)); min-width: 0; max-height: calc(100dvh - 44px); }
